 <TaskEditor v-if="taskEditor" :key="(taskEditor.row?.id||'new')+(taskEditor.preset?.status||'')" :row="taskEditor.row" :preset="taskEditor.preset" @close="taskEditor=null" @saved="saved"/>
 <div v-if="pendingDelete" class="overlay centered" @click.self="!busy&&(pendingDelete=null)"><section class="modal journal-modal" role="dialog" aria-modal="true" aria-label="移入回收站"><h2>移入回收站？</h2><p class="sensitive">{{pendingDelete.row.title}}</p><p>{{pendingDelete.collection==='tasks'?'关联的工作记录会保留，任务以后也可以恢复。':'记录将从当前时间线和搜索中隐藏，以后可以恢复。'}}</p><footer><button class="button secondary" :disabled="!!busy" @click="pendingDelete=null">取消</button><button class="button primary" :disabled="!!busy" @click="remove">{{busy?'正在处理':'移入回收站'}}</button></footer></section></div>
 <div v-if="pinOpen" class="overlay centered" @click.self="pinOpen=false"><form class="modal journal-modal" role="dialog" aria-modal="true" aria-label="固定常用筛选" @submit.prevent="pin"><h2>固定这个查找入口</h2><p>保存当前关键词和筛选条件，下次直接点开。</p><label class="field"><span>入口名称</span><input v-model="pinName" maxlength="60" required placeholder="例如：出差记录、项目 A"/></label><p v-if="pinError" class="error-box" role="alert">{{pinError}}</p><footer><button class="button secondary" type="button" @click="pinOpen=false">取消</button><button class="button primary" :disabled="!!busy">保存入口</button></footer></form></div>
 <div v-if="tagOpen" class="overlay centered" @click.self="!busy&&(tagOpen=false)"><section class="modal journal-modal tag-manager" role="dialog" aria-modal="true" aria-label="管理生活标签"><header><h2>标签管理</h2><button class="icon-button" title="关闭标签管理" :disabled="!!busy" @click="tagOpen=false"><X :size="18"/></button></header><p>点标签可以查找记录。改名或合并前，先查看影响数量。</p><div class="tag-inventory"><span v-for="tag in facets.tags" :key="tag.name"><button @click="searchTag(tag.name);tagOpen=false">#{{tag.name}} <small>{{tag.count}}</small></button><button :aria-label="'改名标签'+tag.name" @click="tagFrom=tag.name;tagTo=''"><Pencil :size="12"/></button></span><p v-if="!facets.tags.length">还没有标签，记一件事时可以直接创建。</p></div><div class="fields-grid"><label class="field"><span>原标签</span><input v-model="tagFrom" list="journal-rename-tags" placeholder="选择或填写标签"/><datalist id="journal-rename-tags"><option v-for="tag in facets.tags" :key="tag.name" :value="tag.name"/></datalist></label><label class="field"><span>改为 / 合并到</span><input v-model="tagTo" maxlength="80" placeholder="新的标签名称"/></label></div><div v-if="tagPreview" class="rename-preview">将更新 {{tagPreview.count}} 条日志或待办。{{tagPreview.message||'正文和记录数量保持不变。'}}</div><p v-if="tagError" class="error-box" role="alert">{{tagError}}</p><footer><button class="button secondary" :disabled="!!busy" @click="previewRename">预览影响</button><button class="button primary" :disabled="!!busy||!tagPreview" @click="renameTag">确认改名 / 合并</button></footer></section></div>
